/** apps/scanner/src/scan/snapshots.ts — vendored offline reference data loader
 * (detector-honesty 3.x, design D3, spec: offline-data-snapshots).
 *
 * The datasets ship as versioned JSON generated by tooling/scripts/refresh-snapshots.ts.
 * Every lookup is a pure function over the vendored data — no socket, no binary.
 * When a datum is absent the caller gets `null`/`[]` and MUST degrade to `unknown`
 * with a what-it-takes note (never a permissive default).
 */
import eolJson from './snapshots/eol.json' with { type: 'json' };
import advisoryJson from './snapshots/advisories.json' with { type: 'json' };

export type EolCycle = { cycle: string; eol: string | null; latest?: string };

type EolDoc = {
  version: string;
  generated_at: string;
  source: string;
  data_date: string;
  runtimes: Record<string, { aliases?: string[]; cycles: EolCycle[] }>;
  frameworks: Record<string, { latest_major: number; support_status: 'active' | 'maintenance' | 'eol'; eol_date?: string | null; aliases?: string[] }>;
  packages: Record<string, Record<string, { latest_major: number; last_release: string; license: string }>>;
};

export type Advisory = {
  id: string;
  ecosystem: string;
  package: string;
  severity: 'CRITICAL' | 'HIGH' | 'MODERATE' | 'LOW';
  introduced: string;
  fixed?: string;
  published: string;
  title: string;
};

type AdvisoryDoc = {
  version: string;
  generated_at: string;
  source: string;
  data_date: string;
  advisories: Advisory[];
};

export const EOL_SNAPSHOT_VERSION: string = (eolJson as unknown as EolDoc).version;
export const ADVISORY_SNAPSHOT_VERSION: string = (advisoryJson as unknown as AdvisoryDoc).version;

/** Version ids of every vendored dataset — the fingerprint inputs (3.3). */
export function snapshotVersions(): Record<string, string> {
  return {
    'eol-snapshot': EOL_SNAPSHOT_VERSION,
    'advisory-snapshot': ADVISORY_SNAPSHOT_VERSION,
  };
}

/** The refresh/re-run hint attached to every absent-datum `unknown` (3.4). */
export const SNAPSHOT_REFRESH_HINT = `refresh the vendored datasets (npx tsx tooling/scripts/refresh-snapshots.ts) or re-run after the snapshot is updated`;

const DAY_MS = 86_400_000;

/** Tolerant numeric version compare: splits on any non-digit run. Unparseable
 * segments compare as 0 (never throws). */
export function cmpVersion(a: string, b: string): number {
  const pa = String(a).split(/[^0-9]+/).filter((x) => x !== '').map((x) => Number(x));
  const pb = String(b).split(/[^0-9]+/).filter((x) => x !== '').map((x) => Number(x));
  const n = Math.max(pa.length, pb.length);
  for (let i = 0; i < n; i++) {
    const x = pa[i] ?? 0;
    const y = pb[i] ?? 0;
    if (x !== y) return x < y ? -1 : 1;
  }
  return 0;
}

function tsOrNull(iso: string | null | undefined): number | null {
  if (!iso) return null;
  const t = Date.parse(iso.length === 10 ? `${iso}T00:00:00Z` : iso);
  return Number.isFinite(t) ? t : null;
}

/** Whole days from the scan instant to an ISO date (negative when in the past). */
export function daysUntil(iso: string | null | undefined, scanMs: number): number | null {
  const t = tsOrNull(iso);
  if (t == null) return null;
  return Math.round((t - scanMs) / DAY_MS);
}

export function monthsSince(iso: string, scanMs: number): number | null {
  const t = tsOrNull(iso);
  if (t == null) return null;
  return Math.floor((scanMs - t) / (30 * DAY_MS));
}

function normalizeProduct(product: string): string | null {
  const doc = eolJson as unknown as EolDoc;
  const p = product.trim().toLowerCase();
  if (doc.runtimes[p]) return p;
  for (const [canonical, entry] of Object.entries(doc.runtimes)) {
    if ((entry.aliases ?? []).includes(p)) return canonical;
  }
  return null;
}

function cycleFor(version: string, cycles: EolCycle[]): EolCycle | null {
  const parts = String(version).split(/[.\-+_]/).filter((x) => x !== '');
  const candidates = [version, parts.slice(0, 2).join('.'), parts[0]].filter(Boolean);
  for (const c of candidates) {
    const hit = cycles.find((x) => x.cycle === c);
    if (hit) return hit;
  }
  // fallback: nearest lower cycle by numeric compare
  const lower = cycles
    .filter((x) => cmpVersion(x.cycle, version) <= 0)
    .sort((a, b) => cmpVersion(b.cycle, a.cycle));
  return lower[0] ?? null;
}

export type RuntimeResolution = {
  product: string;
  version: string;
  cycle: string;
  eol_date: string | null;
  days_until_eol: number | null;
  is_past_eol: boolean;
  latest?: string;
};

/** Resolve a (runtime product, pinned version) to an EOL cycle. `null` when the
 * product is unknown to the snapshot (caller → `unknown`, never "in support"). */
export function resolveRuntime(product: string, version: string, scanMs: number): RuntimeResolution | null {
  const canonical = normalizeProduct(product);
  if (!canonical) return null;
  const doc = eolJson as unknown as EolDoc;
  const cycle = cycleFor(version, doc.runtimes[canonical].cycles);
  if (!cycle) return null;
  const days = daysUntil(cycle.eol, scanMs);
  return {
    product: canonical,
    version,
    cycle: cycle.cycle,
    eol_date: cycle.eol,
    days_until_eol: days,
    is_past_eol: days != null && days < 0,
    latest: cycle.latest,
  };
}

export type FrameworkResolution = {
  name: string;
  version: string;
  support_status: 'active' | 'maintenance' | 'eol';
  eol_date: string | null;
  latest_major: number;
};

/** Resolve a framework to its support status. `null` when the snapshot has no
 * entry for it (niche/vendor framework → `unknown`). */
export function resolveFramework(name: string, version: string): FrameworkResolution | null {
  const doc = eolJson as unknown as EolDoc;
  const key = name.trim().toLowerCase();
  const entry = doc.frameworks[key] ?? doc.frameworks[Object.keys(doc.frameworks).find((k) => (doc.frameworks[k].aliases ?? []).includes(key)) ?? ''];
  if (!entry) return null;
  return {
    name: key,
    version,
    support_status: entry.support_status,
    eol_date: entry.eol_date ?? null,
    latest_major: entry.latest_major,
  };
}

export type PackageResolution = { ecosystem: string; name: string; latest_major: number; last_release: string; license: string };

const ECOSYSTEM_ALIASES: Record<string, string> = { npm: 'js', javascript: 'js', node: 'js', pypi: 'py', pip: 'py', python: 'py', gomod: 'go', golang: 'go', crates: 'rust', maven: 'java', gradle: 'java', mavencentral: 'java', gem: 'ruby', bundler: 'ruby', packagist: 'php', composer: 'php' };

function normalizeEcosystem(ecosystem: string): string {
  const e = ecosystem.trim().toLowerCase();
  return ECOSYSTEM_ALIASES[e] ?? e;
}

/** Package metadata (latest major, last release, license). `null` when absent. */
export function lookupPackage(ecosystem: string, name: string): PackageResolution | null {
  const doc = eolJson as unknown as EolDoc;
  const eco = normalizeEcosystem(ecosystem);
  const bucket = doc.packages[eco];
  if (!bucket) return null;
  const key = name.trim();
  const entry = bucket[key] ?? bucket[key.toLowerCase()];
  if (!entry) return null;
  return { ecosystem: eco, name: key, ...entry };
}

/** Advisories affecting an exact locked version. Empty array == no snapshot entry
 * (the caller reports the dependency unscanned, never clean). */
export function matchAdvisories(ecosystem: string, name: string, version: string): Advisory[] {
  const doc = advisoryJson as unknown as AdvisoryDoc;
  const eco = normalizeEcosystem(ecosystem);
  const key = name.trim();
  return doc.advisories.filter((a) => {
    if (normalizeEcosystem(a.ecosystem) !== eco) return false;
    if (a.package !== key && a.package.toLowerCase() !== key.toLowerCase()) return false;
    if (cmpVersion(version, a.introduced) < 0) return false;
    if (a.fixed && cmpVersion(version, a.fixed) >= 0) return false;
    return true;
  });
}

/** Ecosystems the advisory snapshot covers (for disclosing uncovered ecosystems). */
export function advisoryCoveredEcosystems(): string[] {
  const doc = advisoryJson as unknown as AdvisoryDoc;
  return [...new Set(doc.advisories.map((a) => normalizeEcosystem(a.ecosystem)))].sort();
}

export function advisoryAgeDays(published: string, scanMs: number): number | null {
  const t = tsOrNull(published);
  if (t == null) return null;
  return Math.round((scanMs - t) / DAY_MS);
}
